from fnmatch import fnmatchcase
stmts = [
    {'Effect': 'Allow', 'Action': 's3:*'},
    {'Effect': 'Deny', 'Action': 's3:Delete*'},
]
def check(act):
    hits = {s['Effect'] for s in stmts
            if fnmatchcase(act, s['Action'])}
    return 'Allow' in hits and 'Deny' not in hits
print(check('s3:DeleteObject'), check('s3:GetObject'))

cond = {'StringEquals': {'env': 'prod', 'mfa': 'true'}}
def cond_ok(c, ctx):
    req = c.get('StringEquals', {})
    return all(k in ctx and ctx[k] == v for k, v in req.items())
ctxs = [
    {'env': 'prod', 'mfa': 'true'},
    {'env': 'prod'},
    {'env': 'dev', 'mfa': 'true'},
]
print([cond_ok(cond, x) for x in ctxs])

